function renderDocuments(d){const items=d.items||[];const factLabel={date:"تاریخ",amount:"مبلغ",person_or_party:"شخص/طرف",national_id:"کد ملی",phone:"تلفن"};$("docBody").innerHTML=items.length?`<div class="document-list">${items.map(x=>{const facts=(x.extracted_facts||[]).slice(0,6);return `<article class="document-row" data-document-row="${escapeHtml(x.id)}"><div class="doc-icon">📄</div><div class="doc-main"><strong>${escapeHtml(x.file_name||x.name||"سند")}</strong><span>${escapeHtml(x.mime_type||x.suffix||"")} ${x.page_count?`• ${x.page_count} صفحه`:""} ${x.text_chars?`• ${x.text_chars} نویسه استخراج‌شده`:""}</span><p>${escapeHtml(x.preview||x.text_preview||x.extracted_text_preview||"متن استخراج‌شده برای پیش‌نمایش موجود نیست.")}</p>${facts.length?`<div class="fact-review"><strong>موارد استخراج‌شده — نیازمند تأیید</strong>${facts.map(f=>`<div class="fact-candidate"><span class="mini-tag">${escapeHtml(factLabel[f.type]||f.type)}</span> <b>${escapeHtml(f.value||"")}</b><small>${f.page?`صفحه ${f.page} • `:""}اطمینان تقریبی ${Math.round((Number(f.confidence)||0)*100)}٪</small><p>${escapeHtml(f.snippet||"")}</p></div>`).join("")}${(x.extracted_facts||[]).length>facts.length?`<small>موارد بیشتری نیز استخراج شده‌اند.</small>`:""}<p class="timeline-note">این موارد پیشنهاد ماشینی‌اند؛ پیش از استفاده، با اصل سند تطبیق دهید. تاریخ‌ها بدون تعیین تقویم، به مهلت حقوقی تبدیل نمی‌شوند.</p></div>`:`<small class="timeline-note">مورد ساختاریافته‌ای استخراج نشد یا متن سند کیفیت کافی ندارد.</small>`}</div><div class="doc-actions"><button class="icon-btn mini-icon saved-doc-toggle ${x.saved?'is-saved':''}" data-doc-save="${escapeHtml(x.id)}" data-saved="${x.saved?'1':'0'}" title="${x.saved?'برداشتن نشان':'نشان‌کردن سند'}" aria-label="${x.saved?'برداشتن نشان':'نشان‌کردن سند'}">${x.saved?'★':'☆'}</button><button class="icon-btn mini-icon danger-icon" data-doc-delete="${x.id}" title="حذف">×</button></div></article>`}).join("")}</div>`:`<div class="empty-docs"><span>📄</span><strong>هنوز سندی ثبت نشده</strong><small>PDF، DOCX، TXT و تصاویر را می‌توانید یکجا اضافه کنید.</small></div>`;document.querySelectorAll("[data-doc-delete]").forEach(b=>b.onclick=()=>deleteDocument(b.dataset.docDelete));document.querySelectorAll("[data-doc-save]").forEach(b=>b.onclick=()=>toggleDocumentSaved(b))}
