async function openMyServices(editItem=null){
 let data;try{data=await api('/api/v1/services')}catch(e){showToast(e.message);return}
 const items=data.items||[];
 const form=(x={})=>`<form id="serviceListingForm" class="classic-form service-profile-form" enctype="multipart/form-data"><h3>${x.id?'ویرایش پروفایل خدمت':'ثبت پروفایل خدمت جدید'}</h3>
 <label>نام و نام خانوادگی<input name="full_name" maxlength="120" required value="${escapeHtml(x.full_name||'')}"></label>
 <label>شماره تماس<input name="phone" maxlength="40" required value="${escapeHtml(x.phone||'')}"></label>
 <label>شهر<input name="city" maxlength="100" required value="${escapeHtml(x.city||'')}"></label>
 <label>تخصص<input name="specialty" maxlength="150" required value="${escapeHtml(x.specialty||'')}"></label>
 <label>عنوان خدمت<input name="service_title" maxlength="200" required value="${escapeHtml(x.service_title||'')}"></label>
 <label>نوع دستمزد<select name="fee_type"><option value="fixed" ${x.fee_type==='fixed'?'selected':''}>مبلغ ثابت</option><option value="percent" ${x.fee_type==='percent'?'selected':''}>درصدی</option></select></label>
 <label>مبلغ/درصد توافقی<input name="fee_value" maxlength="100" required value="${escapeHtml(x.fee_value||'')}"></label>
 <label>توضیحات<textarea name="description" maxlength="2000" rows="4">${escapeHtml(x.description||'')}</textarea></label>
 <label class="check-row"><input type="checkbox" name="charitable" ${x.charitable?'checked':''}> خدمت حمایتی / خیریه</label>
 <label>تصویر پروانه وکالت (JPG / PNG / WEBP، حداکثر ۶ مگابایت)<input name="license_photo" type="file" accept="image/jpeg,image/png,image/webp" required></label>
 <p class="timeline-note">تصویر پروانه فقط برای بررسی ادمین به تلگرام ارسال می‌شود و در پروفایل عمومی یا جدول اطلاعات خدمات ذخیره نمی‌شود. با هر ویرایش، پروفایل دوباره در صف بررسی قرار می‌گیرد.</p>
 <button class="primary-btn" type="submit">${x.id?'ثبت و ارسال برای بررسی مجدد':'ثبت و ارسال برای بررسی'}</button><button class="text-btn" type="button" id="serviceCancel">انصراف</button></form>`;
 classicShell('پروفایل خدمات من','خدمات وکالتی خود را مدیریت کنید؛ انتشار عمومی پس از تأیید دستی ادمین انجام می‌شود.',
 `<div id="serviceList">${items.length?items.map(x=>`<article class="classic-result-card service-profile-card"><div class="classic-result-top"><strong>${escapeHtml(x.service_title)}</strong><span class="service-status status-${escapeHtml(x.status)}">${escapeHtml(({pending:'در انتظار بررسی',active:'تأیید شده',rejected:'رد شده'}[x.status]||x.status))}</span></div><p>${escapeHtml(x.city)} · ${escapeHtml(x.specialty)}</p><small>${escapeHtml(x.fee_value)} ${x.fee_type==='fixed'?'تومان':'٪'}</small><div class="client-actions"><button class="secondary-btn" data-service-edit="${x.id}">ویرایش</button><button class="text-btn" data-service-delete="${x.id}">حذف</button></div></article>`).join(''):'<div class="empty-card">هنوز پروفایل خدمتی ثبت نکرده‌اید.</div>'}</div><button class="primary-btn" id="serviceNew">＋ ثبت خدمت جدید</button><div id="serviceFormHost"></div><p class="timeline-note">هر حساب فقط پروفایل‌های متعلق به خودش را مشاهده و مدیریت می‌کند. تأیید یا رد نهایی فقط از طریق پنل ادمین در تلگرام انجام می‌شود.</p>`);
 const host=$('serviceFormHost');
 const bindForm=(x)=>{host.innerHTML=form(x);$('serviceCancel').onclick=()=>{host.innerHTML=''};$('serviceListingForm').onsubmit=async ev=>{ev.preventDefault();const btn=ev.submitter;btn.disabled=true;try{const fd=new FormData(ev.target);const d=await api(x.id?`/api/v1/services/${x.id}`:'/api/v1/services',{method:x.id?'PATCH':'POST',body:fd});showToast(d.notice||'پروفایل ارسال شد.');openMyServices()}catch(e){showToast(e.message);btn.disabled=false}}};
 $('serviceNew').onclick=()=>bindForm();
 $('legalView').querySelectorAll('[data-service-edit]').forEach(b=>b.onclick=()=>bindForm(items.find(x=>String(x.id)===b.dataset.serviceEdit)||{}));
 $('legalView').querySelectorAll('[data-service-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('این پروفایل حذف شود؟'))return;try{await api(`/api/v1/services/${b.dataset.serviceDelete}`,{method:'DELETE'});showToast('پروفایل حذف شد.');openMyServices()}catch(e){showToast(e.message)}});
 if(editItem)bindForm(editItem);
}

