function renderStudentMcqSetup(){
 const levels=studentPracticeCatalog?.levels||[];
 classicShell('تست چهارگزینه‌ای','ابتدا مقطع و سال تحصیلی را انتخاب کنید.',`<form id="studentMcqSetup" class="classic-form"><label>مقطع و سال<select name="level" id="studentLevel" required><option value="">انتخاب کنید…</option>${levels.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.title)}</option>`).join('')}</select></label><label>درس<select name="course_id" id="studentCourse" required disabled><option value="">ابتدا سال را انتخاب کنید</option></select></label><button class="primary-btn" type="submit">شروع آزمون</button><p class="timeline-note">از هر درس حداکثر ۱۰ سؤال به‌صورت تصادفی انتخاب می‌شود.</p></form>`);
 $('studentLevel').onchange=async()=>{const select=$('studentCourse');select.disabled=true;select.innerHTML='<option value="">در حال دریافت درس‌ها…</option>';try{const d=await api(`/api/v1/student-practice/catalog?level=${encodeURIComponent($('studentLevel').value)}`);select.innerHTML='<option value="">انتخاب درس…</option>'+((d.courses||[]).map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.title)} (${faNum(x.count)} سؤال)</option>`).join(''));select.disabled=!(d.courses||[]).length;if(!d.courses?.length)select.innerHTML='<option value="">درسی برای این سال ثبت نشده</option>'}catch(e){select.innerHTML='<option value="">خطا در دریافت درس‌ها</option>';showToast(e.message)}};
 $('studentMcqSetup').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;setBusy(btn,true);try{const d=await api('/api/v1/student-practice/start',{method:'POST',body:JSON.stringify({mode:'mcq',course_id:$('studentCourse').value})});studentPracticeSessionId=d.session_id;renderStudentPracticeQuestion(d)}catch(err){showToast(err.message);btn.disabled=false;btn.textContent='شروع آزمون'}};
}
function renderStudentEssaySetup(){
 const cats=studentPracticeCatalog?.essay_categories||[];
 classicShell('تمرین تشریحی','موضوع را انتخاب کنید؛ ابتدا خودتان پاسخ دهید و سپس پاسخ نمونه را ببینید.',`<form id="studentEssaySetup" class="classic-form"><label>موضوع تمرین<select name="category_id" required><option value="">انتخاب کنید…</option>${cats.map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.title)} (${faNum(x.count)} سؤال)</option>`).join('')}</select></label><button class="primary-btn" type="submit">شروع تمرین</button><p class="timeline-note">${escapeHtml(studentPracticeCatalog?.essay_disclaimer||'پاسخ نمونه راهنمای مطالعه است.')}</p></form>`);
 $('studentEssaySetup').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;setBusy(btn,true);try{const d=await api('/api/v1/student-practice/start',{method:'POST',body:JSON.stringify({mode:'essay',category_id:new FormData(e.target).get('category_id')})});studentPracticeSessionId=d.session_id;renderStudentPracticeQuestion(d)}catch(err){showToast(err.message);btn.disabled=false;btn.textContent='شروع تمرین'}};
}
function renderStudentPracticeQuestion(data,feedback=''){
 const essay=data.mode==='essay',options=data.options||[];
 const body=`<div class="student-practice-progress"><span>${escapeHtml(data.title||'تمرین')}</span><b>سؤال ${faNum(data.index||1)} از ${faNum(data.total||1)}</b></div>${feedback?`<article class="classic-result-card student-feedback"><strong>نتیجه پاسخ قبلی</strong><pre class="classic-pre">${escapeHtml(feedback)}</pre></article>`:''}<article class="student-question-card"><span class="eyebrow">${essay?'ESSAY PRACTICE':'MULTIPLE CHOICE'}</span><h2>${escapeHtml(data.question||'')}</h2>${essay?'<p>پاسخ خود را در ذهن یا روی کاغذ تنظیم کنید؛ سپس پاسخ نمونه را بررسی کنید.</p>':`<div class="student-options">${options.map((x,i)=>`<button type="button" class="student-option" data-student-choice="${i}"><span>${['۱','۲','۳','۴'][i]}</span>${escapeHtml(x)}</button>`).join('')}</div>`}</article>${essay?`<div id="studentEssaySample"></div><div class="student-practice-actions"><button type="button" class="secondary-btn" id="studentShowSample">💡 نمایش پاسخ نمونه</button><button type="button" class="primary-btn" id="studentEssayNext">سؤال بعد ←</button></div>`:''}<p class="timeline-note">${escapeHtml(data.disclaimer||'محتوای این بخش آموزشی است و جایگزین منابع معتبر و تدریس دانشگاهی نیست.')}</p>`;
 classicShell(essay?'تمرین تشریحی':'آزمون چهارگزینه‌ای','پاسخ‌ها و پیشرفت این نشست فقط برای همین حساب نگهداری می‌شوند.',body);
 if(!essay){$('legalView').querySelectorAll('[data-student-choice]').forEach(b=>b.onclick=async()=>{const btn=b;setBusy(btn,true);$('legalView').querySelectorAll('[data-student-choice]').forEach(x=>x.disabled=true);try{const d=await api('/api/v1/student-practice/answer',{method:'POST',body:JSON.stringify({session_id:studentPracticeSessionId,question_token:data.question_token,choice:Number(btn.dataset.studentChoice)})});if(d.finished){renderStudentPracticeFinished(d);return}renderStudentPracticeQuestion({...d.question,mode:'mcq',session_id:studentPracticeSessionId,title:data.title,disclaimer:data.disclaimer},d.feedback)}catch(e){showToast(e.message);$('legalView').querySelectorAll('[data-student-choice]').forEach(x=>x.disabled=false)}})}
 else{$('studentShowSample').onclick=async()=>{const b=$('studentShowSample');setBusy(b,true);try{const d=await api('/api/v1/student-practice/essay-sample',{method:'POST',body:JSON.stringify({session_id:studentPracticeSessionId,question_token:data.question_token})});$('studentEssaySample').innerHTML=`<article class="classic-result-card student-sample-card"><h3>پاسخ نمونه</h3><pre class="classic-pre">${escapeHtml(d.sample)}</pre><small>${escapeHtml(d.disclaimer||'')}</small></article>`;b.disabled=true;b.textContent='پاسخ نمونه نمایش داده شد'}catch(e){showToast(e.message);b.disabled=false;b.textContent='💡 نمایش پاسخ نمونه'}};$('studentEssayNext').onclick=async()=>{const b=$('studentEssayNext');setBusy(b,true);try{const d=await api('/api/v1/student-practice/essay-next',{method:'POST',body:JSON.stringify({session_id:studentPracticeSessionId,question_token:data.question_token})});if(d.finished){renderStudentPracticeFinished(d)}else renderStudentPracticeQuestion(d)}catch(e){showToast(e.message);b.disabled=false;b.textContent='سؤال بعد ←'}}}
}
function renderStudentPracticeFinished(data){studentPracticeSessionId=null;const score=data.correct!==undefined?`<div class="calculator-result-value">${faNum(data.correct)} از ${faNum(data.total)} پاسخ درست</div>`:'<div class="student-practice-emblem">🏁</div>';classicShell('پایان تمرین','این نوبت از تمرین به پایان رسید.',`<article class="classic-result-card student-finish-card"><h2>آفرین؛ تمرین تمام شد.</h2>${score}<p>${escapeHtml(data.disclaimer||'برای تثبیت یادگیری، پاسخ‌ها را با منابع درسی تطبیق دهید.')}</p><button type="button" class="primary-btn" id="studentPracticeAgain">تمرین جدید</button></article>`);$('studentPracticeAgain').onclick=renderStudentPracticeHome}

function openClassicSearch(){
 classicShell('جست‌وجوی حقوقی یکپارچه','جست‌وجو در بانک منابع حقوقی و واژه‌نامه موجود در بات.',
 `<form id="classicSearchForm" class="classic-form"><label>عبارت جست‌وجو<input id="classicSearchQuery" maxlength="200" required placeholder="مثلاً ماده ۱۰ قانون مدنی یا رأی وحدت رویه ۸۱۰"></label><button class="primary-btn" type="submit">جست‌وجو</button></form><div id="classicSearchResults"></div>`);
 $('classicSearchForm').onsubmit=async e=>{e.preventDefault();const q=$('classicSearchQuery').value.trim();if(q.length<2)return;const root=$('classicSearchResults');root.innerHTML='<div class="loading-box">در حال جست‌وجو در منابع…</div>';try{const d=await api(`/api/v1/legal-search?q=${encodeURIComponent(q)}&limit=10`);const items=d.items||[],gloss=d.glossary||[];root.innerHTML=`<div class="classic-result-summary">${items.length} منبع حقوقی · ${gloss.length} مدخل واژه‌نامه</div>${items.length?items.map((x,i)=>`<article class="classic-result-card"><div class="classic-result-top"><strong>${escapeHtml(x.title)}</strong><span>${escapeHtml(x.kind||'')}</span></div><small>${escapeHtml(x.law||'')}${x.article?' · '+escapeHtml(x.article):''}${x.source_page?' · صفحه '+escapeHtml(x.source_page):''}</small><p>${escapeHtml(x.snippet||'متن گزیده در دسترس نیست.')}</p>${x.citation_id?`<button class="secondary-btn compact-btn" data-source="${escapeHtml(x.citation_id)}">مشاهده منبع و ارتباط‌ها</button>`:''}</article>`).join(''):'<div class="empty-card"><strong>منبعی پیدا نشد.</strong><span>ممکن است عبارت در بانک فعلی موجود نباشد.</span></div>'}${gloss.length?`<h3 class="classic-subhead">واژه‌نامه حقوقی</h3>${gloss.map(x=>`<article class="classic-result-card"><strong>${escapeHtml(x.term)}</strong><p>${escapeHtml(x.definition)}</p></article>`).join('')}`:''}<p class="timeline-note">${escapeHtml(d.notice||'')}</p>`;root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openLegalSource(b.dataset.source));}catch(err){root.innerHTML=`<div class="empty-card">${escapeHtml(err.message)}</div>`}};
}
async function openLegalSource(id){const root=$('classicSearchResults');try{const d=await api(`/api/v1/legal-search/source?id=${encodeURIComponent(id)}`),x=d.item;root.innerHTML=`<button class="text-btn" id="sourceBack">← بازگشت به نتایج</button><article class="classic-result-card"><h2>${escapeHtml(x.title)}</h2><small>${escapeHtml(x.law||'')}${x.article?' · '+escapeHtml(x.article):''}</small><pre class="classic-pre">${escapeHtml(x.text||'متن منبع موجود نیست.')}</pre><p class="timeline-note">${escapeHtml(x.notice||'')}</p><h3>اطلاعات منبع</h3><p>${escapeHtml(JSON.stringify(x.citation||{},null,2))}</p><h3>منابع مرتبط پیشنهادی</h3>${(x.related||[]).map(r=>`<p>${escapeHtml(r.title)} ${r.citation_id?`<button class="text-btn" data-source="${escapeHtml(r.citation_id)}">بازکردن</button>`:''}</p>`).join('')}</article>`;$('sourceBack').onclick=openClassicSearch;root.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openLegalSource(b.dataset.source));}catch(e){showToast(e.message)}}
async function openClients(){
 classicShell('مدیریت موکلین','اطلاعات موکل به‌صورت خصوصی در حساب شما نگهداری می‌شود.',
 `<div class="classic-form"><h3>افزودن موکل</h3><form id="clientCreateForm"><label>نام و نام خانوادگی<input id="clientName" maxlength="120" required></label><label>شماره تماس<input id="clientPhone" maxlength="40" inputmode="tel"></label><label>شناسه ملی (اختیاری)<input id="clientNationalId" maxlength="20"></label><label>یادداشت<textarea id="clientNote" maxlength="2000" rows="2"></textarea></label><button class="primary-btn" type="submit">＋ ثبت موکل</button></form></div><div class="classic-form"><label>جست‌وجوی موکل<input id="clientSearch" type="search" placeholder="نام یا شماره تماس"></label><div id="clientList" class="client-list"><div class="loading-box">در حال دریافت موکلین…</div></div></div>`);
 const load=async()=>{try{const d=await api(`/api/v1/clients?q=${encodeURIComponent($('clientSearch').value.trim())}&limit=100`);const root=$('clientList');root.innerHTML=(d.items||[]).length?(d.items||[]).map(c=>`<article class="client-row"><div><strong>${escapeHtml(c.name)}</strong><small>${escapeHtml(c.phone||'بدون شماره')} · ${escapeHtml(c.note||'')}</small></div><div class="client-actions"><button class="secondary-btn compact-btn" data-client-view="${c.id}">پرونده‌ها</button><button class="secondary-btn compact-btn" data-client-edit="${c.id}">ویرایش</button><button class="text-btn danger-text" data-client-delete="${c.id}">حذف</button></div></article>`).join(''):'<div class="empty-card"><strong>موکلی ثبت نشده است.</strong></div>';
 root.querySelectorAll('[data-client-view]').forEach(b=>b.onclick=()=>viewClient(b.dataset.clientView));root.querySelectorAll('[data-client-edit]').forEach(b=>b.onclick=()=>editClient(b.dataset.clientEdit));root.querySelectorAll('[data-client-delete]').forEach(b=>b.onclick=()=>deleteClient(b.dataset.clientDelete));}catch(e){$('clientList').innerHTML=`<div class="empty-card">${escapeHtml(e.message)}</div>`}};
 $('clientCreateForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/v1/clients',{method:'POST',body:JSON.stringify({name:$('clientName').value.trim(),phone:$('clientPhone').value.trim(),national_id:$('clientNationalId').value.trim(),note:$('clientNote').value.trim()})});e.target.reset();showToast('موکل ثبت شد.');load()}catch(err){showToast(err.message)}};
 $('clientSearch').oninput=()=>{clearTimeout(window.__clientSearch);window.__clientSearch=setTimeout(load,250)};load();
}
async function viewClient(id){try{const d=await api(`/api/v1/clients/${id}`),c=d.item,linked=d.cases||[];const root=$('clientList');root.innerHTML=`<button class="text-btn" id="clientListBack">← بازگشت به فهرست</button><article class="classic-result-card"><h3>${escapeHtml(c.name)}</h3><p>تماس: ${escapeHtml(c.phone||'ثبت نشده')}<br>شناسه ملی: ${escapeHtml(c.national_id||'ثبت نشده')}<br>یادداشت: ${escapeHtml(c.note||'—')}</p><h4>پرونده‌های مرتبط (${linked.length})</h4>${linked.map(x=>`<p>${escapeHtml(x.file_name||'پرونده بدون نام')}</p>`).join('')||'<p>هنوز پرونده‌ای متصل نشده است.</p>'}<label>اتصال به پرونده<select id="clientCaseSelect"><option value="">انتخاب پرونده</option>${cases.filter(x=>x.status!=='archived').map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.file_name||x.name)}</option>`).join('')}</select></label><button class="primary-btn" id="clientLinkCase">اتصال پرونده</button></article>`;$('clientListBack').onclick=openClients;$('clientLinkCase').onclick=async()=>{const cid=$('clientCaseSelect').value;if(!cid)return showToast('پرونده را انتخاب کنید.');try{await api(`/api/v1/clients/${id}/cases/${cid}`,{method:'POST',body:'{}'});showToast('پرونده متصل شد.');viewClient(id)}catch(e){showToast(e.message)}};}catch(e){showToast(e.message)}}
async function editClient(id){try{const d=await api(`/api/v1/clients/${id}`),c=d.item;$('modalRoot').hidden=false;$('modalRoot').innerHTML=`<div class="modal-backdrop" id="clientEditBackdrop"><section class="modal"><div class="modal-head"><h2>ویرایش موکل</h2><button class="icon-btn" id="clientEditClose">×</button></div><label>نام<input id="clientEditName" maxlength="120" value="${escapeHtml(c.name)}"></label><label>شماره تماس<input id="clientEditPhone" maxlength="40" value="${escapeHtml(c.phone||'')}"></label><label>شناسه ملی<input id="clientEditNational" maxlength="20" value="${escapeHtml(c.national_id||'')}"></label><label>یادداشت<textarea id="clientEditNote" maxlength="2000">${escapeHtml(c.note||'')}</textarea></label><button class="primary-btn" id="clientEditSave">ذخیره</button></section></div>`;$('clientEditClose').onclick=closeModal;$('clientEditBackdrop').onclick=e=>{if(e.target.id==='clientEditBackdrop')closeModal()};$('clientEditSave').onclick=async()=>{try{await api(`/api/v1/clients/${id}`,{method:'PATCH',body:JSON.stringify({name:$('clientEditName').value,phone:$('clientEditPhone').value,national_id:$('clientEditNational').value,note:$('clientEditNote').value})});closeModal();showToast('اطلاعات ویرایش شد.');openClients()}catch(e){showToast(e.message)}};}catch(e){showToast(e.message)}}
async function deleteClient(id){if(!confirm('موکل حذف شود؟ پرونده‌های مرتبط حذف نمی‌شوند.'))return;try{await api(`/api/v1/clients/${id}`,{method:'DELETE'});showToast('موکل حذف شد.');openClients()}catch(e){showToast(e.message)}}
async function openCalculators(){
 let catalog;try{catalog=await api('/api/v1/calculators')}catch(e){showToast(e.message);return}
 classicShell('محاسبات حقوقی','محاسبه‌گرهای محلی و فرمول‌محور؛ خروجی‌ها برآوردند و باید با تعرفه و داده رسمی کنترل شوند.',
 `<form id="calculatorForm" class="classic-form"><label>نوع محاسبه<select id="calculatorKind">${catalog.items.map(x=>`<option value="${x.id}">${escapeHtml(x.title)}</option>`).join('')}</select></label><div id="calculatorFields"></div><button class="primary-btn" type="submit">محاسبه</button></form><div id="calculatorResult"></div><details class="classic-form"><summary>مبنا و وضعیت داده‌های محاسبه‌گرها</summary>${Object.entries(catalog.source_notes||{}).map(([k,v])=>`<p class="timeline-note"><strong>${escapeHtml(k)}:</strong> ${escapeHtml(v)}</p>`).join('')}<p class="timeline-note">شاخص مهریه سال‌های ۱۴۰۳ و ۱۴۰۴ در جدول موجود تقریبی/علی‌الحساب علامت‌گذاری شده‌اند. محاسبه خسارت تأخیر به شاخص‌های رسمی ورودی شما وابسته است.</p></details>`);
 const fields=()=>{const k=$('calculatorKind').value,years=catalog.mahr_years||[];let html='';if(k==='mahr')html=`<label>مبلغ مهریه (تومان)<input name="amount" inputmode="decimal" required></label><label>سال عقد<select name="contract_year">${years.map(y=>`<option value="${y.year}">${y.year}${y.provisional?' · تقریبی':''}</option>`).join('')}</select></label>`;else if(k==='diya')html=`<label>نوع محاسبه<select name="mode" id="diyaMode"><option value="full_normal">دیه کامل ماه غیرحرام</option><option value="full_haram">دیه کامل ماه حرام (با احراز شرایط)</option><option value="head">جراحات سر و صورت</option><option value="color">تغییر رنگ پوست</option><option value="custom">درصد دلخواه از دیه کامل غیرحرام</option></select></label><label id="diyaPresetLabel" hidden>نوع جراحت/تغییر رنگ<select name="preset" id="diyaPreset"></select></label><label id="diyaPercentLabel" hidden>درصد<input name="percent" type="number" min="0" max="100" step="0.01" value="5"></label><p class="timeline-note">ارش عدد ثابت ندارد و در این محاسبه‌گر عددسازی نمی‌شود. درصد جراحات و تغییر رنگ با مبنای غیرحرام محاسبه می‌شود.</p>`;else if(k==='delay')html=`<label>اصل دین (تومان)<input name="principal" required inputmode="decimal"></label><label>شاخص مبدأ<input name="index_start" type="number" min="0" step="any" required></label><label>شاخص مقصد<input name="index_end" type="number" min="0" step="any" required></label>`;else if(k==='court_fee')html=`<label>بهای خواسته (ریال)<input name="amount_rial" required inputmode="decimal"></label><label>مرحله<select name="stage"><option value="first">بدوی</option><option value="appeal">تجدیدنظر</option><option value="supreme">فرجام/مرحله بالاتر</option></select></label>`;else if(k==='lawyer_fee')html=`<label>بهای خواسته (ریال)<input name="amount_rial" required inputmode="decimal"></label>`;else if(k==='deadline')html=`<label>تاریخ ابلاغ (شمسی یا میلادی)<input name="start_date" required placeholder="۱۴۰۵/۰۶/۱۲ یا 2026-09-03"></label><label>تعداد روز تقویمی<input name="days" type="number" min="0" max="3650" required></label>`;else if(k==='quick_percent')html=`<label>مبلغ (تومان)<input name="amount" inputmode="decimal" required></label><label>درصد<input name="percent" type="number" min="0" max="10000" step="any" required></label>`;else if(k==='rial_convert')html=`<label>مبلغ<input name="amount" inputmode="decimal" required></label><label>جهت تبدیل<select name="direction"><option value="toman_to_rial">تومان به ریال</option><option value="rial_to_toman">ریال به تومان</option></select></label>`;else if(k==='installment')html=`<label>کل مبلغ (تومان)<input name="total" inputmode="decimal" required></label><label>تعداد اقساط<input name="count" type="number" min="1" max="600" required></label>`;else if(k==='date_diff')html=`<label>تاریخ اول (شمسی یا میلادی)<input name="date_a" required placeholder="۱۴۰۵/۰۶/۲۹ یا 2026/09/20"></label><label>تاریخ دوم (شمسی یا میلادی)<input name="date_b" required placeholder="۱۴۰۵/۰۷/۱۰ یا 2026/09/30"></label>`;else if(k==='date_convert')html=`<label>تاریخ شمسی یا میلادی<input name="value" required placeholder="۱۴۰۵/۰۶/۲۹ یا 2026/09/20"></label>`;else if(k==='iran_today')html=`<p class="timeline-note">تاریخ و ساعت فعلی بر اساس منطقه زمانی ایران (Asia/Tehran) دریافت می‌شود.</p>`;else if(k==='alcohol_fine')html=`<label>ارزش عرفی مشروبات مکشوفه (تومان)<input name="value_toman" inputmode="decimal" required></label>`;$('calculatorFields').innerHTML=html;if(k==='diya'){const mode=$('diyaMode'),presetLabel=$('diyaPresetLabel'),percentLabel=$('diyaPercentLabel'),preset=$('diyaPreset');const update=()=>{const v=mode.value,presetMode=['head','color'].includes(v);presetLabel.hidden=!presetMode;percentLabel.hidden=v!=='custom';preset.required=presetMode;$('calculatorFields').querySelector('[name=percent]').required=v==='custom';if(presetMode){const items=catalog.diyah_presets?.[v]||{};preset.innerHTML=Object.entries(items).map(([name,pct])=>`<option value="${escapeHtml(name)}">${escapeHtml(name)} · ${escapeHtml(pct)}٪</option>`).join('')}};mode.onchange=update;update()}};
 $('calculatorKind').onchange=fields;fields();$('calculatorForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data={kind:$('calculatorKind').value};for(const [k,v] of f.entries())data[k]=v;const root=$('calculatorResult');root.innerHTML='<div class="loading-box">در حال محاسبه…</div>';try{const d=await api('/api/v1/calculators/run',{method:'POST',body:JSON.stringify(data)});const r=d.result,mainValue=r.amount??r.damage??r.days??r.output??r.end_date_jalali??r.end_date??r.jalali??'—';root.innerHTML=`<article class="classic-result-card"><h3>نتیجه محاسبه</h3><div class="calculator-result-value">${escapeHtml(mainValue)} ${escapeHtml(r.unit|| (['mahr','diya','delay','quick_percent','installment','alcohol_fine'].includes(r.kind)?'تومان':r.kind==='date_diff'?'روز':''))}</div><pre class="classic-pre">${escapeHtml(Object.entries(r).filter(([k])=>!['kind'].includes(k)).map(([k,v])=>`${k}: ${typeof v==='object'?JSON.stringify(v):v}`).join('\n'))}</pre>${r.warning?`<p class="timeline-note">${escapeHtml(r.warning)}</p>`:''}${r.provisional?'<p class="library-note">شاخص حداقل یکی از سال‌ها تقریبی/علی‌الحساب است؛ قبل از استناد با جدول رسمی تطبیق دهید.</p>':''}</article>`}catch(err){root.innerHTML=`<div class="empty-card">${escapeHtml(err.message)}</div>`}};
}
function openGuides(){
 const catalogs={check:{role:[['holder','دارنده چک / طلبکار'],['drawer','صادرکننده / ظهرنویس']],topics:{holder:[['exec','اجرای ثبت / اجرائیه چک'],['claim','مطالبه حقوقی وجه چک'],['crime','جنبه کیفری'],['docs','مدارک و مهلت‌ها']],drawer:[['defense','دفاع در برابر مطالبه'],['pay','پرداخت / تعیین موجودی'],['crime_d','پاسخ به شکایت کیفری'],['docs','مدارک ضروری']]}},family:{role:[['creditor','طلبکار مهریه'],['debtor','بدهکار مهریه']],topics:{creditor:[['claim','مطالبه مهریه'],['index','به‌روز کردن مهریه'],['exec','اجرا / توقیف'],['install','توافق یا تقسیط']],debtor:[['esar','اعسار'],['install','تقسیط'],['object','اعتراض به میزان مطالبه'],['lift','رفع محدودیت اجرا']]}},ejare:{role:[['tenant','مستأجر'],['landlord','موجر']],topics:{tenant:[['ceiling','افزایش اجاره بیش از سقف'],['deposit','استرداد ودیعه'],['renew','تمدید یا پایان قرارداد'],['evict_threat','تهدید به تخلیه']],landlord:[['evict','درخواست تخلیه'],['unpaid','عدم پرداخت اجاره'],['end_term','پایان مدت قرارداد'],['damage','خسارت به ملک']]}},shora:{topic:[['check','چک / سفته / طلب مالی'],['rent','اجاره و تخلیه'],['damage','خسارت جزئی / تصادف'],['neighbor','اختلاف همسایگی'],['other','سایر']],amount:[['low','زیر ۵۰ میلیون'],['mid','۵۰ تا ۱۰۰ میلیون'],['high','بیش از ۱۰۰ میلیون'],['unknown','نمی‌دانم']],docs:[['yes','مدرک دارم'],['partial','مدرک ناقص دارم'],['no','مدرک ندارم']]},tax:{activity:[['shop','فروش کالا / آنلاین‌شاپ'],['service','خدمات / فریلنسری'],['rent','اجاره ملک'],['commission','پورسانتی / کارمزدی'],['home','کسب‌وکار خانگی'],['other','سایر']],task:[['register','ثبت‌نام مالیاتی'],['return','اظهارنامه / فرم'],['notice','بررسی ابلاغیه'],['reduce','کاهش قانونی مالیات'],['unknown','نمی‌دانم از کجا شروع کنم']],income:[['low','زیر ۱۰۰ میلیون'],['mid','۱۰۰ تا ۵۰۰ میلیون'],['high','۵۰۰ میلیون تا ۱ میلیارد'],['large','بیش از ۱ میلیارد'],['unknown','نمی‌دانم']],docs:[['yes','مدارک دارم'],['no','مدارک ندارم'],['unknown','نامشخص']]}};
 classicShell('راهنماهای تخصصی','راهنماهای موجود بات در Mini App؛ پاسخ‌ها با همان موتورهای محلی تولید می‌شوند و AI مصرف نمی‌کنند.',
 `<form id="guideForm" class="classic-form"><label>نوع راهنما<select id="guideKind"><option value="check">چک و سفته</option><option value="ejare">اجاره و تخلیه</option><option value="family">مهریه و اعسار</option><option value="shora">شورا و دادگاه صلح</option><option value="tax">مالیاتی</option></select></label><div id="guideFields"></div><button class="primary-btn" type="submit">ساخت راهنما</button></form><div id="taxScreenBox" class="classic-form" hidden><h3>بررسی تصویر صفحه مالیاتی</h3><label>تصویر صفحه مالیاتی<input id="taxScreenPicker" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="secondary-btn" id="taxScreenRun" type="button">OCR محلی و توضیح صفحه</button><small>تصویر فقط برای OCR محلی پردازش می‌شود؛ فرم رسمی پر یا ارسال نمی‌شود.</small></div><div id="guideResult"></div>`);
 const select=(name,label,items)=>`<label>${label}<select name="${name}">${items.map(([v,l])=>`<option value="${v}">${escapeHtml(l)}</option>`).join('')}</select></label>`;
 const fields=()=>{const k=$('guideKind').value,c=catalogs[k];let html='';if(c.role){html+=select('role','نقش',c.role);html+=`<label>موضوع<select name="topic" id="guideTopic"></select></label>`}else if(k==='shora'){html+=select('topic','موضوع',c.topic)+select('amount','حدود مبلغ',c.amount)+select('docs','وضعیت مدارک',c.docs)}else{html+=select('activity','نوع فعالیت',c.activity)+select('task','کار موردنظر',c.task)+select('income','حدود درآمد',c.income)+select('docs','وضعیت مدارک',c.docs)}$('guideFields').innerHTML=html;$('taxScreenBox').hidden=k!=='tax';if(c.role){const update=()=>{$('guideTopic').innerHTML=c.topics[$('guideForm').elements.role.value].map(([v,l])=>`<option value="${v}">${escapeHtml(l)}</option>`).join('')};$('guideForm').elements.role.onchange=update;update()}};
 $('guideKind').onchange=fields;fields();wireTaxScreen();$('guideForm').onsubmit=async e=>{e.preventDefault();const data={};for(const [k,v] of new FormData(e.target).entries())data[k]=v;const root=$('guideResult');root.innerHTML='<div class="loading-box">در حال ساخت راهنما…</div>';try{const d=await api(`/api/v1/guides/${$('guideKind').value}`,{method:'POST',body:JSON.stringify(data)});root.innerHTML=`<article class="classic-result-card"><h3>راهنمای آماده‌شده</h3><pre class="classic-pre">${escapeHtml(d.text)}</pre><p class="timeline-note">${escapeHtml(d.notice||'')}</p><button class="secondary-btn" id="copyGuide">کپی متن</button></article>`;$('copyGuide').onclick=async()=>{try{await navigator.clipboard.writeText(d.text);showToast('متن راهنما کپی شد.')}catch(_){showToast('کپی خودکار در این محیط پشتیبانی نمی‌شود.')}}}catch(err){root.innerHTML=`<div class="empty-card">${escapeHtml(err.message)}</div>`}};
}
function openGuidedTrees(){
 const kinds=[['contract','قرارداد و تعهدات'],['claims','مطالبات و دیون'],['property','املاک و مالکیت'],['check','چک'],['lease','اجاره']];
 classicShell('درخت‌های بررسی پرونده','درخت‌های تصمیم داخلی بات؛ بدون AI و با پاسخ‌های مرحله‌ای و قابل بازبینی.',
 `<div class="classic-form"><label>پرونده<select id="treeCase"><option value="">انتخاب پرونده</option>${cases.filter(x=>x.status!=='archived').map(x=>`<option value="${escapeHtml(x.id)}">${escapeHtml(x.file_name||x.name)}</option>`).join('')}</select></label><label>نوع بررسی<select id="treeKind">${kinds.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</select></label><button class="primary-btn" id="treeStart">شروع بررسی</button></div><div id="treeBody"></div>`);
 $('treeStart').onclick=async()=>{const cid=$('treeCase').value;if(!cid)return showToast('ابتدا پرونده را انتخاب کنید.');const root=$('treeBody');root.innerHTML='<div class="loading-box">در حال آماده‌سازی درخت…</div>';try{const kind=$('treeKind').value,d=await api(`/api/v1/guided-trees/${kind}/start`,{method:'POST',body:JSON.stringify({case_id:Number(cid)})});activeTreeSessionId=d.session_id;activeTreeKind=kind;renderTreeState(d.state,d.node,root,d.summary)}catch(e){root.innerHTML=`<div class="empty-card">${escapeHtml(e.message)}</div>`}};
}
function renderTreeState(state,node,root,summary=null){
 if(state?.status==='complete'||String(state?.status||'').startsWith('not_')){root.innerHTML=`<article class="classic-result-card"><h3>نتیجه درخت بررسی</h3><pre class="classic-pre">${escapeHtml(JSON.stringify(summary||state,null,2))}</pre><p class="timeline-note">نتیجه ساختاریافته موتور داخلی است؛ برای خوانایی و کنترل، داده‌ها و اسناد اصلی را بررسی کنید.</p></article>`;activeTreeSessionId=null;return}
 if(!node){root.innerHTML='<div class="empty-card"><strong>مرحله پرسش در دسترس نیست.</strong><span>درخت را دوباره شروع کنید.</span></div>';return}
 root.innerHTML=`<article class="classic-result-card"><div class="classic-result-summary">مرحله ${Number(state.index||0)+1}</div><h3>${escapeHtml(node.title||'پرسش')}</h3><p>${escapeHtml(node.question||'')}</p><div class="tree-choice-list">${(node.choices||[]).map(([label,code])=>`<button class="secondary-btn" data-tree-choice="${escapeHtml(code)}">${escapeHtml(label)}</button>`).join('')}</div></article>`;
 root.querySelectorAll('[data-tree-choice]').forEach(b=>b.onclick=async()=>{try{const d=await api(`/api/v1/guided-trees/${activeTreeKind}/step`,{method:'POST',body:JSON.stringify({session_id:activeTreeSessionId,choice:b.dataset.treeChoice})});const r=d.result;renderTreeState(r.state,r.node,root,r.summary)}catch(e){showToast(e.message)}});
}

async function openReferrals(){
 classicShell('معرفی‌های وکالت','درخواست‌های معرفی وکیل و فرصت‌های معرفی‌شده برای شما.',`<form id="referralCreateForm" class="classic-form"><h3>ثبت درخواست معرفی وکیل</h3><label>موضوع یا حوزه پرونده<input name="topic" maxlength="160" required placeholder="مثلاً اختلاف قرارداد مشارکت"></label><label>شهر<input name="city" maxlength="100" required placeholder="شهر موردنظر"></label><label>فوریت<select name="urgency"><option value="normal">عادی</option><option value="soon">نسبتاً فوری</option><option value="urgent">فوری</option></select></label><label>شرح مختصر موضوع<textarea name="details" minlength="10" maxlength="4000" rows="4" required placeholder="خواسته و اطلاعات ضروری را بنویسید؛ نام، شماره تماس، کد ملی یا مدارک محرمانه وارد نکنید."></textarea></label><label class="pref-check-option"><input name="consent" type="checkbox" required><span>موافقم شرح بدون اطلاعات تماس برای بررسی درخواست در اختیار پشتیبانی و وکیل منتخب قرار گیرد.</span></label><button class="primary-btn" type="submit">ثبت درخواست معرفی</button></form><div id="referralsBody" class="loading-box">در حال دریافت معرفی‌ها…</div>`);
 const root=$('referralsBody');$('referralCreateForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data={topic:String(f.get('topic')||'').trim(),city:String(f.get('city')||'').trim(),urgency:f.get('urgency'),details:String(f.get('details')||'').trim(),consent:f.get('consent')==='on'};const b=e.submitter;setBusy(b,true);try{const created=await api('/api/v1/referrals',{method:'POST',body:JSON.stringify(data)});showToast(`درخواست معرفی #${created.id} ثبت شد.`);await openReferrals()}catch(err){showToast(err.message)}finally{b.disabled=false;b.textContent='ثبت درخواست معرفی'}};try{const d=await api('/api/v1/referrals'),own=d.own_requests||[],incoming=d.incoming_matches||[];const statusMap={new:'جدید',sent:'ارسال‌شده برای وکیل',more_info:'اطلاعات بیشتر خواسته شده',contact:'در حال ارتباط',closed:'بسته‌شده',declined:'ردشده',cancelled:'لغوشده',accepted:'پذیرفته‌شده'};root.innerHTML=`<section class="classic-form"><h3>معرفی‌های دریافتی برای شما (${incoming.length})</h3>${incoming.length?incoming.map(x=>`<article class="classic-result-card"><div class="classic-result-top"><strong>درخواست #${escapeHtml(x.referral_id)}</strong><span>${escapeHtml(statusMap[x.status]||x.status)}</span></div><p><strong>موضوع:</strong> ${escapeHtml(x.topic||'—')}<br><strong>شهر:</strong> ${escapeHtml(x.city||'—')}<br><strong>فوریت:</strong> ${escapeHtml(x.urgency||'عادی')}<br><strong>شرح:</strong> ${escapeHtml(x.details||'—')}</p><small>خدمت شما: ${escapeHtml(x.service_title||'—')} · ${escapeHtml(x.specialty||'')}</small>${['sent','more_info'].includes(x.status)?`<div class="client-actions"><button class="primary-btn compact-btn" data-referral-action="accepted" data-match="${x.id}">پذیرش اولیه</button><button class="secondary-btn compact-btn" data-referral-action="more_info" data-match="${x.id}">درخواست اطلاعات بیشتر</button><button class="text-btn danger-text" data-referral-action="declined" data-match="${x.id}">رد معرفی</button></div>`:''}</article>`).join(''):'<div class="empty-card"><strong>فعلاً معرفی دریافتی ندارید.</strong><span>اگر معرفی جدیدی به خدمات شما اختصاص یابد، اینجا نمایش داده می‌شود.</span></div>'}</section><section class="classic-form"><h3>درخواست‌های معرفی ثبت‌شده (${own.length})</h3>${own.length?own.map(x=>`<article class="client-row"><strong>درخواست #${x.id} · ${escapeHtml(x.topic)}</strong><small>${escapeHtml(x.city)} · ${escapeHtml(x.urgency)} · ${escapeHtml(statusMap[x.status]||x.status)}</small></article>`).join(''):'<div class="empty-card">درخواستی ثبت نکرده‌اید.</div>'}</section><p class="timeline-note">${escapeHtml(d.notice||'')}</p>`;
 root.querySelectorAll('[data-referral-action]').forEach(b=>b.onclick=async()=>{const status=b.dataset.referralAction,mid=b.dataset.match;const promptText=status==='more_info'?'توضیح اختیاری برای درخواست اطلاعات بیشتر را بنویسید:':'یادداشت اختیاری (در صورت نیاز):';let note='';if(status==='more_info'||status==='declined'){note=window.prompt(promptText,'')||''}if(status==='declined'&&!confirm('این معرفی رد شود؟'))return;setBusy(b,true);try{const result=await api(`/api/v1/referrals/matches/${mid}`,{method:'POST',body:JSON.stringify({status,note})});showToast(status==='accepted'?'پذیرش اولیه ثبت شد.':status==='declined'?'رد معرفی ثبت شد.':'درخواست اطلاعات بیشتر ثبت شد.');await openReferrals()}catch(e){showToast(e.message)}finally{b.disabled=false}});
 }catch(e){root.innerHTML=`<div class="empty-card">${escapeHtml(e.message)}</div>`}
}

function openSupportHelp(){
 classicShell('راهنما و پشتیبانی','راهنمای کوتاه استفاده از میزکار و ارسال پیام به پشتیبانی.',
 `<section class="classic-result-card"><h3>از کجا شروع کنم؟</h3><p>۱) از «کمد پرونده‌ها» پرونده بسازید و اسناد را اضافه کنید.<br>۲) ابزارهای مستقل از AI در بخش «ابزارها و خدمات حقوقی» قرار دارند.<br>۳) تحلیل، پرسش حقوقی، نگارش، کتابخانه و Playbookها در زیرمنوی «هوش مصنوعی» هستند.<br>۴) تاریخ‌های استخراج‌شده در تقویم نمایش داده می‌شوند؛ برای آن‌ها می‌توانید یادآوری یک روز قبل فعال کنید.<br>۵) نتایج محاسبات و راهنماها را با منابع رسمی و اسناد اصلی کنترل کنید.</p></section><form id="supportForm" class="classic-form"><h3>ارسال پیام یا گزارش مشکل</h3><label>نوع پیام<select name="kind"><option value="support">درخواست پشتیبانی</option><option value="user_report">گزارش خطا یا پیشنهاد</option></select></label><label>شرح پیام<textarea name="message" maxlength="4000" rows="5" required placeholder="مشکل یا پیشنهاد خود را توضیح دهید…"></textarea></label><button class="primary-btn" type="submit">ارسال به پشتیبانی</button><small>متن پیام در پایگاه داده پشتیبانی ثبت می‌شود. اطلاعات محرمانه موکل یا اسناد پرونده را در پیام عمومی وارد نکنید.</small></form><div id="supportResult"></div>`);
 $('supportForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),message=String(f.get('message')||'').trim();if(!message)return;const b=e.submitter;setBusy(b,true);try{await api('/api/v1/feedback',{method:'POST',body:JSON.stringify({kind:f.get('kind'),message,context:'Mini App support'})});$('supportResult').innerHTML='<div class="library-note">پیام شما ثبت شد. ممنون از بازخوردتان.</div>';e.target.reset()}catch(err){showToast(err.message)}finally{b.disabled=false;b.textContent='ارسال به پشتیبانی'}};
}

async function loadContractPlaybooks(){const root=$('contractPlaybooksList');if(!root)return;try{const d=await api('/api/v1/contract-playbooks');const items=d.items||[];root.innerHTML=items.map(x=>`<article class="workflow-active-card"><strong>${escapeHtml(x.title)}</strong><p>${escapeHtml(x.description||'')}</p><button class="secondary-btn compact-btn" data-run-playbook="${escapeHtml(x.id)}">انتخاب پرونده و بررسی</button></article>`).join('')||'<div class="empty-card">الگوی آماده‌ای موجود نیست.</div>';root.querySelectorAll('[data-run-playbook]').forEach(b=>b.onclick=()=>openPlaybookCasePicker(b.dataset.runPlaybook,items.find(x=>x.id===b.dataset.runPlaybook)?.title||'بررسی قرارداد'));}catch(e){root.innerHTML=`<div class="empty-card">${escapeHtml(e.message)}</div>`}}
