// MACHINA playful atelier controls: real local time/date, current-month calendar,
// and strictly decorative latch/calibration interactions.
function updateMachinaClock(){
  const now=new Date();
  const clock=$('machinaClock'), date=$('machinaDate');
  if(clock) clock.textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);
  if(date) date.textContent=new Intl.DateTimeFormat('fa-IR',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now);
  const monthLabel=$('calendarMonth'), daysRoot=$('calendarDays');
  if(!monthLabel||!daysRoot)return;
  monthLabel.textContent=new Intl.DateTimeFormat('fa-IR',{month:'short'}).format(now);
  const year=now.getFullYear(), month=now.getMonth(), first=new Date(year,month,1), total=new Date(year,month+1,0).getDate();
  // Calendar headings are Persian week order (Saturday first); JS Sunday=0 -> offset Saturday=0.
  const offset=(first.getDay()+1)%7;
  const cells=[];
  for(let i=0;i<offset;i++)cells.push('<span class="calendar-day empty" aria-hidden="true">·</span>');
  for(let day=1;day<=total;day++){
    const today=day===now.getDate();
    cells.push(`<span class="calendar-day${today?' today':''}"${today?' aria-current="date"':''}>${new Intl.NumberFormat('fa-IR',{useGrouping:false}).format(day)}</span>`);
  }
  daysRoot.innerHTML=cells.join('');
}
updateMachinaClock();setInterval(updateMachinaClock,1000);
