// Small hidden atelier hatch on dynamically rendered workspace/account menus.
// It is purely decorative and never changes case data or operational status.
(function initAtelierHatches(){
  const roots=[$('workspace'),$('legalView'),$('modalRoot')].filter(Boolean);
  const messages={
    'پیش‌نویس':'کشوی کاغذها: مرتب‌سازی نمایشی انجام شد. هیچ متنی تغییر نکرده است.',
    'کارهای پرونده':'فنرِ فهرست: یک تقِ نمایشی. وضعیت کارها دست‌نخورده ماند.',
    'یادداشت وکیل':'محفظهٔ یادداشت‌ها باز شد؛ این دریچه به متن خصوصی دسترسی جداگانه‌ای ندارد.',
    'شواهد':'رادار خاموش است؛ این افکت هیچ مدرکی را بررسی نمی‌کند.',
    'تحلیل حقوقی':'مقیاس تحلیل روی حالت تزئینی تنظیم شد؛ نتیجهٔ حقوقی تغییر نکرد.',
    'حساب کاربری':'پنل خدمات باز شد. اطلاعات حساب یا اعتبار تغییر نکرد.',
    'پرسش حقوقی':'دریچهٔ ارتباطات باز شد؛ این افکت پیامی به هوش مصنوعی نمی‌فرستد.'
  };
  function detailFor(head){
    const text=(head?.innerText||'').replace(/\s+/g,' ');
    const key=Object.keys(messages).find(k=>text.includes(k));
    return key?messages[key]:'یک محفظهٔ مخفی از کارگاه MACHINA. تزئینی محض؛ عملیات واقعی تغییری نکرد.';
  }
  function decorate(root){
    root.querySelectorAll('.panel-head,.modal-head').forEach(head=>{
      if(head.dataset.atelierHatchReady==='1')return;
      if(!head.closest('#workspace,#legalView,#modalRoot'))return;
      head.dataset.atelierHatchReady='1';
      const button=document.createElement('button');
      button.type='button';button.className='atelier-hatch-trigger';button.textContent='⊙';
      button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','باز کردن دریچهٔ مخفی تزئینی');
      button.title='دریچهٔ خدماتی مخفی';
      head.appendChild(button);
      const drawer=document.createElement('div');drawer.className='atelier-secret-drawer';drawer.hidden=true;
      drawer.innerHTML='<span class="atelier-drawer-pipe" aria-hidden="true"></span><span class="atelier-drawer-glyph" aria-hidden="true">✣</span><span class="atelier-drawer-copy"></span><span class="atelier-drawer-code" aria-hidden="true">M-07 / NON ESSENTIAL</span>';
      head.insertAdjacentElement('afterend',drawer);
      drawer.querySelector('.atelier-drawer-copy').textContent=detailFor(head);
    });
  }
  roots.forEach(root=>{
    decorate(root);
    new MutationObserver(()=>decorate(root)).observe(root,{childList:true,subtree:true});
  });
  document.addEventListener('click',event=>{
    const button=event.target.closest('.atelier-hatch-trigger');if(!button)return;
    const head=button.closest('.panel-head,.modal-head');const drawer=head?.nextElementSibling;
    if(!drawer?.classList.contains('atelier-secret-drawer'))return;
    const open=button.getAttribute('aria-expanded')!=='true';
    button.setAttribute('aria-expanded',String(open));drawer.hidden=!open;
    button.classList.toggle('is-spun',open);
    if(open){const copy=drawer.querySelector('.atelier-drawer-copy');if(copy)copy.textContent=detailFor(head);}
  });
  // Hidden calibration trick: three quick taps on a service hatch produce a tiny compass spin.
  document.addEventListener('click',event=>{
    const button=event.target.closest('.atelier-hatch-trigger');if(!button)return;
    const now=Date.now(),last=Number(button.dataset.lastTap||0),count=Number(button.dataset.tapCount||0);
    const next=now-last<700?count+1:1;button.dataset.tapCount=String(next);button.dataset.lastTap=String(now);
    if(next>=3){button.dataset.tapCount='0';button.classList.remove('is-secret-spin');void button.offsetWidth;button.classList.add('is-secret-spin');showToast('قطب‌نمای کارگاه یک دور کامل زد. جهت پرونده‌ها تغییر نکرد! 🧭');}
  });
})();

