// Three camouflaged MACHINA extras: tiny challenge, local unit converter, ghost lights + optional ambient tones.
const microModal=(eyebrow,title,body)=>{
  const root=$('modalRoot'),opener=document.activeElement;root.hidden=false;
  root.innerHTML=`<div class="modal-backdrop machina-extra-backdrop" id="machinaExtraBackdrop"><section class="modal machina-extra-modal" role="dialog" aria-modal="true" aria-labelledby="machinaExtraTitle"><div class="modal-head"><div><span class="eyebrow">${eyebrow}</span><h2 id="machinaExtraTitle">${title}</h2></div><button class="icon-btn" id="machinaExtraClose" aria-label="بستن">×</button></div>${body}</section></div>`;
  const onKeydown=e=>{if(e.key==='Escape'){e.preventDefault();close()}};
  const close=()=>{root.removeEventListener('keydown',onKeydown);root.hidden=true;root.innerHTML='';if(opener&&opener.isConnected)opener.focus()};
  root.addEventListener('keydown',onKeydown);
  $('machinaExtraClose').onclick=close;
  $('machinaExtraBackdrop').onclick=e=>{if(e.target.id==='machinaExtraBackdrop')close()};
  $('machinaExtraClose').focus();
  return {root,close};
};
